function uid(prefix: string) { return `${prefix}-${crypto.randomUUID()}`; }
function inputNumber(value: FormDataEntryValue | null) { return Number(String(value ?? "0").replace(",", ".")) || 0; }
function formatDate(value: string) { return new Intl.DateTimeFormat(activeLocale, { day: "2-digit", month: "short", year: "numeric" }).format(new Date(`${value}T12:00:00`)); }
function operationIdFromPath() { return window.location.pathname.match(/^\/operacoes\/([^/]+)$/)?.[1] ?? null; }
function cnpjRaw(value: string) { return value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 14); }
function cepRaw(value: string) { return value.replace(/\D/g, "").slice(0, 8); }
function formatCep(value: string) { const raw = cepRaw(value); return raw.length > 5 ? `${raw.slice(0, 5)}-${raw.slice(5)}` : raw; }
function formatCnpj(value: string) { const raw = cnpjRaw(value); return [raw.slice(0, 2), raw.slice(2, 5), raw.slice(5, 8), raw.slice(8, 12), raw.slice(12, 14)].filter(Boolean).map((part, index) => index === 0 ? part : index === 3 ? `/${part}` : index === 4 ? `-${part}` : `.${part}`).join(""); }
function cnpjDigit(value: string) { const weights = value.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]; const remainder = [...value].reduce((sum, character, index) => sum + (character.charCodeAt(0) - 48) * weights[index], 0) % 11; return remainder < 2 ? 0 : 11 - remainder; }
function isValidCnpj(value: string) { const raw = cnpjRaw(value); if (raw.length !== 14 || (/^\d+$/.test(raw) && /^([0-9])\1+$/.test(raw))) return false; const base = raw.slice(0, 12); const first = cnpjDigit(base); return Number(raw[12]) === first && Number(raw[13]) === cnpjDigit(`${base}${first}`); }
function viewFromPath(): View { const path = window.location.pathname; if (path === "/home") return "dashboard"; if (path.startsWith("/operacoes")) return "imports"; if (path === "/clientes") return "customers"; if (path === "/portos") return "ports"; if (path === "/relatorios") return "reports"; if (path === "/pendencias") return "pending"; if (path === "/usuarios") return "users"; if (path === "/meu-perfil") return "profile"; return "dashboard"; }
function viewUrl(view: View) { return ({ dashboard: "/home", imports: "/operacoes", customers: "/clientes", ports: "/portos", reports: "/relatorios", pending: "/pendencias", users: "/usuarios", profile: "/meu-perfil" } as const)[view]; }
type OperationsFilters = { query: string; status: ImportStatus | "all"; channel: CustomsSignal | "all"; sort: "oldest" | "newest" | "updated"; page: number };
function operationsFiltersFromUrl(): OperationsFilters { const params = new URLSearchParams(window.location.search); const status = params.get("status"); const channel = params.get("channel"); const sort = params.get("sort"); return { query: params.get("search") ?? "", status: status && status in importStatusMeta ? status as ImportStatus : "all", channel: channel && channel in customsChannelMeta ? channel as CustomsSignal : "all", sort: sort === "newest" || sort === "updated" ? sort : "oldest", page: Math.max(1, Number(params.get("page")) || 1) }; }
function operationsUrl(filters: OperationsFilters) { const params = new URLSearchParams(); if (filters.query) params.set("search", filters.query); if (filters.status !== "all") params.set("status", filters.status); if (filters.channel !== "all") params.set("channel", filters.channel); if (filters.sort !== "oldest") params.set("sort", filters.sort); if (filters.page > 1) params.set("page", String(filters.page)); const query = params.toString(); return `/operacoes${query ? `?${query}` : ""}`; }
function Skeleton({ className = "" }: { className?: string }) { return <span className={`skeleton ${className}`} aria-hidden="true" />; }
function TableSkeletonRows({ columns, rows = 6 }: { columns: number; rows?: number }) { return <>{Array.from({ length: rows }, (_, row) => <tr className="skeleton-row" key={row}>{Array.from({ length: columns }, (_, column) => <td key={column}><Skeleton className={`skeleton--table skeleton--table-${column}`} /></td>)}</tr>)}</>; }
